//! `sermofur_core::atomic::write` against the table that the .NET code produced
//! (`rust/tests/golden/atomic-file.json`, regenerated by `rust/tools/atomic-oracle`).

use std::fs;
use std::path::{Path, PathBuf};
#[cfg(windows)]
use std::process::Command;
use std::sync::OnceLock;

use serde_json::{Map, Value};
use sermofur_core::atomic::{LinkPolicy, WriteError, WriteOptions, write};
use sermofur_core::error::SermofurError;
use uuid::Uuid;

fn golden() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/golden/atomic-file.json"
    );
    let text = fs::read_to_string(path).expect("the golden file exists");
    serde_json::from_str(&text).expect("the golden file is valid JSON")
}

/// The temporary directory, resolved once; on macOS `/var` is a link, so it is canonicalized
/// everywhere but on Windows (where `canonicalize` adds the `\\?\` prefix).
fn temp_base() -> &'static Path {
    static BASE: OnceLock<PathBuf> = OnceLock::new();
    BASE.get_or_init(|| {
        let dir = std::env::temp_dir();
        if cfg!(windows) {
            dir
        } else {
            fs::canonicalize(dir).expect("the temporary directory resolves")
        }
    })
}

/// A fresh folder, removed on drop.
struct TempRoot(PathBuf);

impl TempRoot {
    fn new() -> Self {
        let root = temp_base().join(format!("sermofur-atomic-{}", Uuid::new_v4()));
        fs::create_dir_all(&root).expect("temp root");
        Self(root)
    }
}

impl Drop for TempRoot {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

/// A link to a directory: a junction on Windows (`mklink /J`, never refused), else a symlink.
fn junction(link: &Path, target: &Path) {
    #[cfg(windows)]
    {
        let out = Command::new("cmd")
            .args(["/C", "mklink", "/J"])
            .arg(link)
            .arg(target)
            .output()
            .expect("cmd runs");
        assert!(out.status.success(), "mklink /J failed: {out:?}");
    }
    #[cfg(not(windows))]
    std::os::unix::fs::symlink(target, link).expect("symlink");
}

/// A symbolic link; false (with the reason printed) when the machine refuses it.
fn symlink(link: &Path, target: &Path, to_folder: bool) -> bool {
    #[cfg(windows)]
    let made = if to_folder {
        std::os::windows::fs::symlink_dir(target, link)
    } else {
        std::os::windows::fs::symlink_file(target, link)
    };
    #[cfg(not(windows))]
    let made = {
        let _ = to_folder;
        std::os::unix::fs::symlink(target, link)
    };
    if let Err(error) = &made {
        eprintln!("symlink creation refused ({error})");
    }
    made.is_ok()
}

fn chain(root: &Path, links: usize) -> bool {
    fs::write(root.join("target"), "old").expect("target");
    for i in (0..links).rev() {
        let next = if i == links - 1 {
            "target".to_owned()
        } else {
            format!("l{}", i + 1)
        };
        if !symlink(&root.join(format!("l{i}")), &root.join(next), false) {
            return false;
        }
    }
    true
}

/// Prepares the folder of a scenario like the oracle does; false when a symlink is refused.
fn prepare(name: &str, root: &Path) -> bool {
    let old = |file: &str| fs::write(root.join(file), "old").expect("old file");
    let mkdir = |dir: &str| fs::create_dir_all(root.join(dir)).expect("folder");
    let file_link = |link: &str, target: PathBuf| symlink(&root.join(link), &target, false);
    match name {
        "new_file" | "missing_parent_folders" | "follow_new_file" => true,
        "replace_existing" | "follow_no_link" => {
            old("a.txt");
            true
        }
        "refuse_symlink_to_file" | "follow_one_link" => {
            old("target");
            file_link("link", root.join("target"))
        }
        "refuse_dangling_symlink" | "follow_dangling" => file_link("link", root.join("nowhere")),
        "refuse_folder" => {
            mkdir("folder");
            true
        }
        "follow_folder_itself" => {
            mkdir("dir");
            true
        }
        "refuse_junction" | "follow_junction" => {
            mkdir("dir");
            junction(&root.join("junction"), &root.join("dir"));
            true
        }
        "follow_relative_link" => {
            mkdir("sub");
            fs::write(root.join("sub").join("target"), "old").expect("target");
            file_link("link", Path::new("sub").join("target"))
        }
        "follow_relative_dot_dot" => {
            mkdir("sub");
            old("target");
            file_link("sub/link", Path::new("..").join("target"))
        }
        "follow_chain_10" => chain(root, 10),
        "follow_chain_11" => chain(root, 11),
        "follow_circle" => file_link("a", root.join("b")) && file_link("b", root.join("a")),
        "follow_self" => file_link("a", root.join("a")),
        "follow_to_folder" => {
            mkdir("dir");
            symlink(&root.join("link"), &root.join("dir"), true)
        }
        "follow_link_to_link_to_file" => {
            old("target");
            file_link("l2", root.join("target")) && file_link("l1", root.join("l2"))
        }
        "follow_case_variant_circle" => {
            file_link("a", root.join("b")) && file_link("b", root.join("A"))
        }
        other => panic!("unknown scenario {other}"),
    }
}

/// What the folder holds: every entry, its kind and the content of plain files.
fn listing(root: &Path) -> Value {
    fn walk(dir: &Path, root: &Path, out: &mut Map<String, Value>) {
        for entry in fs::read_dir(dir).expect("read_dir") {
            let path = entry.expect("entry").path();
            let relative = path
                .strip_prefix(root)
                .expect("inside")
                .to_string_lossy()
                .replace('\\', "/");
            let kind = fs::symlink_metadata(&path).expect("metadata").file_type();
            if kind.is_symlink() {
                out.insert(relative, "link".into());
            } else if kind.is_dir() {
                out.insert(relative, "folder".into());
                walk(&path, root, out);
            } else {
                let text = fs::read_to_string(&path).expect("text");
                out.insert(relative, text.into());
            }
        }
    }
    let mut out = Map::new();
    walk(root, root, &mut out);
    Value::Object(out)
}

fn show(root: &Path, text: &str) -> String {
    text.replace(root.to_string_lossy().as_ref(), "<root>")
        .replace('\\', "/")
}

#[test]
fn every_scenario_matches_the_oracle() {
    let golden = golden();
    let rows = golden["scenarios"].as_array().expect("scenarios");
    assert_eq!(rows.len(), 22);
    let (mut matched, mut skipped) = (0, Vec::new());
    let mut mismatches = Vec::new();
    let allow_skip = std::env::var("SERMOFUR_ALLOW_SYMLINK_SKIP").is_ok_and(|v| v == "1");
    for row in rows {
        let name = row["name"].as_str().expect("a name");
        let mut row = row.clone();
        // A circle only on a case-insensitive comparison, which only Windows applies (ordinal
        // elsewhere). Linux: `A` does not exist, so the chain ends on a missing file and the
        // row cannot match. macOS: the default APFS is case-insensitive, so `A` is `a`, the
        // chain comes back to `<root>/b` and is a circle there (as .NET with its ordinal
        // comparison does).
        if name == "follow_case_variant_circle" && !cfg!(windows) {
            if cfg!(target_os = "macos") {
                row["message"] =
                    "<root>/a was left untouched: its links come back to <root>/b, in a circle."
                        .into();
            } else {
                skipped.push(format!("{name}: case-insensitive comparison only"));
                continue;
            }
        }
        let root = TempRoot::new();
        if !prepare(name, &root.0) {
            if allow_skip {
                skipped.push(format!("{name}: symlink creation refused"));
            } else {
                mismatches.push(format!(
                    "{name}: symlink creation refused (SERMOFUR_ALLOW_SYMLINK_SKIP=1 allows it)"
                ));
            }
            continue;
        }
        let options = WriteOptions {
            policy: if row["policy"] == "follow" {
                LinkPolicy::FollowToTarget
            } else {
                LinkPolicy::Refuse
            },
            ..WriteOptions::default()
        };
        let file = row["file"].as_str().expect("a file");
        let outcome = write(&root.0.join(file), b"new", &options);
        let mut problems = Vec::new();
        match (&outcome, row["code"].as_str()) {
            (Ok(path), None) => {
                let got = show(&root.0, &path.to_string_lossy());
                if Some(got.as_str()) != row["written"].as_str() {
                    problems.push(format!("written {got}, expected {}", row["written"]));
                }
            }
            (Err(WriteError::Refused(e)), Some(code)) => {
                let got = (
                    e.code.as_str(),
                    show(&root.0, &e.message),
                    i64::from(e.exit_code),
                );
                let want = (
                    code,
                    row["message"].as_str().expect("message").to_owned(),
                    row["exitCode"].as_i64().expect("exit code"),
                );
                if got != want {
                    problems.push(format!("error {got:?}, expected {want:?}"));
                }
            }
            _ => problems.push(format!("outcome {outcome:?}, expected {row}")),
        }
        let after = listing(&root.0);
        if after != row["after"] {
            problems.push(format!("folder {after}, expected {}", row["after"]));
        }
        if problems.is_empty() {
            matched += 1;
        } else {
            mismatches.push(format!("{name}: {}", problems.join("; ")));
        }
    }
    eprintln!("atomic scenarios: {matched} matched, skipped: {skipped:?}");
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

#[test]
fn a_non_durable_write_gives_the_same_result() {
    let root = TempRoot::new();
    let options = WriteOptions {
        durable: false,
        ..WriteOptions::default()
    };
    let written = write(&root.0.join("a.txt"), b"x", &options).expect("write");
    assert_eq!(fs::read(written).expect("read"), b"x");
    assert_eq!(listing(&root.0)["a.txt"], "x");
    assert_eq!(listing(&root.0).as_object().expect("map").len(), 1);
}

#[cfg(unix)]
#[test]
fn modes_survive_the_umask() {
    use std::os::unix::fs::PermissionsExt;
    let root = TempRoot::new();
    let mode_of = |p: &Path| fs::metadata(p).expect("metadata").permissions().mode() & 0o7777;

    let existing = root.0.join("existing");
    fs::write(&existing, "old").expect("old");
    fs::set_permissions(&existing, fs::Permissions::from_mode(0o640)).expect("chmod");
    let options = WriteOptions {
        new_file_mode: Some(0o666),
        ..WriteOptions::default()
    };
    write(&existing, b"new", &options).expect("replace");
    assert_eq!(mode_of(&existing), 0o640);

    let fresh = root.0.join("fresh");
    write(&fresh, b"new", &options).expect("create");
    assert_eq!(mode_of(&fresh), 0o666);
}

#[test]
fn a_trailing_separator_creates_the_folder_and_fails_with_io() {
    let root = TempRoot::new();
    let asked = format!(
        "{}{}x.txt{}",
        root.0.display(),
        std::path::MAIN_SEPARATOR,
        std::path::MAIN_SEPARATOR
    );
    let error = write(Path::new(&asked), b"x", &WriteOptions::default()).expect_err("fails");
    assert!(matches!(error, WriteError::Io(_)), "{error:?}");
    assert_eq!(listing(&root.0)["x.txt"], "folder");
    let converted = SermofurError::from(error);
    assert_eq!(
        (converted.code.as_str(), converted.exit_code),
        ("invalid_storage_or_path", 3)
    );
}

#[cfg(unix)]
#[test]
fn the_final_target_of_a_link_keeps_its_own_mode() {
    use std::os::unix::fs::PermissionsExt;
    let root = TempRoot::new();
    let target = root.0.join("target");
    fs::write(&target, "old").expect("old");
    fs::set_permissions(&target, fs::Permissions::from_mode(0o640)).expect("chmod");
    std::os::unix::fs::symlink(&target, root.0.join("link")).expect("symlink");
    let options = WriteOptions {
        new_file_mode: Some(0o666),
        policy: LinkPolicy::FollowToTarget,
        ..WriteOptions::default()
    };
    write(&root.0.join("link"), b"new", &options).expect("write");
    let mode = fs::metadata(&target)
        .expect("metadata")
        .permissions()
        .mode()
        & 0o7777;
    assert_eq!(mode, 0o640);
}

/// A target held open without `FILE_SHARE_DELETE` cannot be replaced. On Unix a rename over a
/// file cannot be made to fail portably (the checks refuse a folder first), so Windows only.
#[cfg(windows)]
#[test]
fn a_failing_rename_leaves_the_target_intact_and_no_temporary() {
    use std::os::windows::fs::OpenOptionsExt;
    let root = TempRoot::new();
    let target = root.0.join("a.txt");
    fs::write(&target, "old").expect("old");
    let held = fs::OpenOptions::new()
        .read(true)
        .share_mode(0)
        .open(&target)
        .expect("held");
    let result = write(&target, b"new", &WriteOptions::default());
    drop(held);
    let error = result.expect_err("the rename fails");
    assert!(matches!(error, WriteError::Io(_)), "{error:?}");
    assert_eq!(fs::read_to_string(&target).expect("read"), "old");
    assert_eq!(
        listing(&root.0)
            .as_object()
            .expect("map")
            .keys()
            .collect::<Vec<_>>(),
        ["a.txt"]
    );
}

#[test]
fn a_refused_folder_keeps_the_trailing_separator_in_the_message() {
    let root = TempRoot::new();
    fs::create_dir(root.0.join("folder")).expect("folder");
    let sep = std::path::MAIN_SEPARATOR;
    let asked = format!("{}{sep}folder{sep}", root.0.display());
    let Err(WriteError::Refused(e)) = write(Path::new(&asked), b"x", &WriteOptions::default())
    else {
        panic!("a folder is refused");
    };
    assert_eq!(
        show(&root.0, &e.message),
        "<root>/folder/ was left untouched: it is a folder."
    );
}
